{"file_path": "src/lib/utils/retry-utils.ts", "initial_content": "/**
 * Retry utility functions with exponential backoff
 */

import { RetryConfig, GenerationAttempt } from '@/types';
import { logger } from './logger';

/**
 * Default retry configuration
 */
export const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  initialDelayMs: 1000, // 1 second
  maxDelayMs: 10000, // 10 seconds
  backoffMultiplier: 2,
};

/**
 * Sleep for a specified duration
 */
const sleep = (ms: number): Promise<void> => 
  new Promise(resolve => setTimeout(resolve, ms));

/**
 * Calculate delay for exponential backoff
 */
function calculateBackoffDelay(
  attemptNumber: number,
  config: RetryConfig
): number {
  const delay = config.initialDelayMs * Math.pow(config.backoffMultiplier, attemptNumber - 1);
  return Math.min(delay, config.maxDelayMs);
}

/**
 * Determine if an error is retryable
 */
function isRetryableError(error: unknown): boolean {
  if (error instanceof Error) {
    const message = error.message.toLowerCase();

    // Network errors - retryable
    if (message.includes('network') || 
        message.includes('timeout') || 
        message.includes('econnrefused') ||
        message.includes('econnreset')) {
      return true;
    }

    // Rate limiting - retryable
    if (message.includes('rate limit') || 
        message.includes('too many requests')) {
      return true;
    }

    // Service unavailable - retryable
    if (message.includes('503') || 
        message.includes('service unavailable')) {
      return true;
    }

    // Model loading - retryable (Ollama specific)
    if (message.includes('model is loading')) {
      return true;
    }
  }

  // Validation errors, auth errors - NOT retryable
  return false;
}

/**
 * Execute a function with retry logic and exponential backoff
 * 
 * @param fn - The async function to execute
 * @param config - Retry configuration
 * @param context - Context for logging (e.g., section ID)
 * @returns The result of the function or throws after all retries exhausted
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  config: RetryConfig = DEFAULT_RETRY_CONFIG,
  context?: string
): Promise<T> {
  const attempts: GenerationAttempt[] = [];
  let lastError: unknown;

  for (let attemptNumber = 1; attemptNumber <= config.maxAttempts; attemptNumber++) {
    const attempt: GenerationAttempt = {
      attemptNumber,
      model: context || 'unknown',
      startTime: Date.now(),
      success: false,
    };

    try {
      logger.info(`Attempt ${attemptNumber}/${config.maxAttempts}${context ? ` for ${context}` : ''}`);

      const result = await fn();

      attempt.success = true;
      attempt.endTime = Date.now();
      attempts.push(attempt);

      if (attemptNumber > 1) {
        logger.info(`✓ Succeeded on attempt ${attemptNumber} after ${attempt.endTime - attempt.startTime}ms`);
      }

      return result;

    } catch (error) {
      attempt.success = false;
      attempt.endTime = Date.now();
      attempt.error = error instanceof Error ? error.message : String(error);
      attempts.push(attempt);

      lastError = error;

      // Check if error is retryable
      if (!isRetryableError(error)) {
        logger.error(`✗ Non-retryable error on attempt ${attemptNumber}: ${attempt.error}`);
        throw error;
      }

      // If this was the last attempt, don't wait
      if (attemptNumber === config.maxAttempts) {
        logger.error(`✗ All ${config.maxAttempts} attempts failed`);
        break;
      }

      // Calculate backoff delay and wait
      const delay = calculateBackoffDelay(attemptNumber, config);
      logger.warn(`✗ Attempt ${attemptNumber} failed: ${attempt.error}. Retrying in ${delay}ms...`);
      await sleep(delay);
    }
  }

  // All attempts failed
  const totalTime = attempts.reduce((sum, a) => sum + ((a.endTime || 0) - a.startTime), 0);
  logger.error(`Failed after ${attempts.length} attempts (total time: ${totalTime}ms)`);

  throw lastError;
}

/**
 * Execute multiple functions with retry logic in parallel
 * Returns partial results - some may succeed while others fail
 */
export async function withRetryParallel<T>(
  fns: Array<() => Promise<T>>,
  config: RetryConfig = DEFAULT_RETRY_CONFIG,
  contexts?: string[]
): Promise<Array<{ success: boolean; result?: T; error?: Error }>> {
  const promises = fns.map((fn, index) => 
    withRetry(fn, config, contexts?.[index])
      .then(result => ({ success: true as const, result }))
      .catch(error => ({ 
        success: false as const, 
        error: error instanceof Error ? error : new Error(String(error)) 
      }))
  );

  return Promise.all(promises);
}
"}

{"file_path": "src/lib/utils/model-selector.ts", "initial_content": "/**
 * AI Model Selection Logic
 * Dynamically selects the best model based on task complexity
 */

import { ModelConfig, SectionComplexity } from '@/types';
import { Section } from '@/lib/models/section';
import { logger } from './logger';

/**
 * Model configurations for different complexity levels
 */
const MODEL_CONFIGS: Record<SectionComplexity, ModelConfig> = {
  [SectionComplexity.SIMPLE]: {
    model: 'ollama/gemma:2b',
    temperature: 0.3,
    maxTokens: 1000,
  },
  [SectionComplexity.MEDIUM]: {
    model: 'ollama/phi3:mini',
    temperature: 0.4,
    maxTokens: 2000,
  },
  [SectionComplexity.COMPLEX]: {
    model: 'ollama/llama3:8b',
    temperature: 0.5,
    maxTokens: 3000,
  },
  [SectionComplexity.EXPERT]: {
    model: 'ollama/qwen2.5:latest',
    temperature: 0.6,
    maxTokens: 4000,
  },
};

/**
 * Determine section complexity based on various factors
 */
export function assessSectionComplexity(section: Section): SectionComplexity {
  let complexityScore = 0;

  // Factor 1: Word count requirement
  const wordCount = section.controls?.wordCount || 0;
  if (wordCount > 1500) complexityScore += 3;
  else if (wordCount > 800) complexityScore += 2;
  else if (wordCount > 400) complexityScore += 1;

  // Factor 2: Number of guidelines
  const guidelinesCount = section.guidelines?.length || 0;
  if (guidelinesCount > 5) complexityScore += 2;
  else if (guidelinesCount > 2) complexityScore += 1;

  // Factor 3: Complexity control
  const complexity = section.controls?.complexity || 50;
  if (complexity > 80) complexityScore += 3;
  else if (complexity > 60) complexityScore += 2;
  else if (complexity > 40) complexityScore += 1;

  // Factor 4: Context dependencies
  const contextCount = (section.context?.length || 0) + (section.externalContext?.length || 0);
  if (contextCount > 5) complexityScore += 2;
  else if (contextCount > 2) complexityScore += 1;

  // Factor 5: Behaviors complexity
  const behaviorsCount = section.behaviors?.length || 0;
  if (behaviorsCount > 3) complexityScore += 1;

  // Factor 6: Section type
  if (section.type === 'diagram' || section.type === 'table') {
    complexityScore += 2; // Structured content is more complex
  }

  // Map score to complexity level
  if (complexityScore >= 9) return SectionComplexity.EXPERT;
  if (complexityScore >= 6) return SectionComplexity.COMPLEX;
  if (complexityScore >= 3) return SectionComplexity.MEDIUM;
  return SectionComplexity.SIMPLE;
}

/**
 * Select the appropriate model configuration for a section
 */
export function selectModelForSection(section: Section): ModelConfig {
  const complexity = assessSectionComplexity(section);
  const config = MODEL_CONFIGS[complexity];

  logger.info(`Selected model: ${config.model} (complexity: ${complexity}, section: ${section.title})`);

  return config;
}

/**
 * Get model config by complexity level (for testing or manual selection)
 */
export function getModelConfig(complexity: SectionComplexity): ModelConfig {
  return MODEL_CONFIGS[complexity];
}

/**
 * Override model selection with custom configuration
 * Useful for testing or user preferences
 */
export function createCustomModelConfig(
  modelName?: string,
  temperature?: number,
  maxTokens?: number
): ModelConfig {
  return {
    model: modelName || MODEL_CONFIGS[SectionComplexity.MEDIUM].model,
    temperature: temperature ?? 0.4,
    maxTokens: maxTokens ?? 2000,
  };
}
"}

{"file_path": "src/lib/utils/rate-limiter.ts", "initial_content": "/**
 * Rate Limiting Utilities
 * In-memory rate limiting for API endpoints
 * TODO: Use Redis for production with multiple server instances
 */

import { RateLimitInfo } from '@/types';
import { logger } from './logger';

/**
 * Rate limit configuration per user tier
 */
interface RateLimitConfig {
  windowMs: number; // Time window in milliseconds
  maxRequests: number; // Maximum requests per window
}

/**
 * Default rate limits by user role
 */
const RATE_LIMITS: Record<string, RateLimitConfig> = {
  free: {
    windowMs: 60 * 1000, // 1 minute
    maxRequests: 5, // 5 generations per minute
  },
  premium: {
    windowMs: 60 * 1000, // 1 minute
    maxRequests: 20, // 20 generations per minute
  },
  admin: {
    windowMs: 60 * 1000, // 1 minute
    maxRequests: 100, // 100 generations per minute
  },
};

/**
 * In-memory store for rate limit tracking
 * Key: userId, Value: RateLimitInfo
 */
const rateLimitStore = new Map<string, RateLimitInfo>();

/**
 * Clean up expired rate limit entries (runs periodically)
 */
function cleanupExpiredEntries(): void {
  const now = Date.now();
  for (const [userId, info] of rateLimitStore.entries()) {
    if (info.windowEnd < now) {
      rateLimitStore.delete(userId);
    }
  }
}

// Run cleanup every 5 minutes
setInterval(cleanupExpiredEntries, 5 * 60 * 1000);

/**
 * Get rate limit configuration for a user
 */
function getRateLimitConfig(userRole?: string): RateLimitConfig {
  const role = userRole?.toLowerCase() || 'free';
  return RATE_LIMITS[role] || RATE_LIMITS.free;
}

/**
 * Check if user has exceeded rate limit
 * 
 * @param userId - User ID to check
 * @param userRole - User role (free, premium, admin)
 * @returns RateLimitInfo with current status
 */
export function checkRateLimit(userId: string, userRole?: string): RateLimitInfo {
  const config = getRateLimitConfig(userRole);
  const now = Date.now();

  // Get or create rate limit info for user
  let info = rateLimitStore.get(userId);

  if (!info || info.windowEnd < now) {
    // Create new window
    info = {
      userId,
      requestCount: 0,
      windowStart: now,
      windowEnd: now + config.windowMs,
      limit: config.maxRequests,
    };
    rateLimitStore.set(userId, info);
  }

  return info;
}

/**
 * Increment rate limit counter for a user
 * 
 * @param userId - User ID
 * @param userRole - User role
 * @returns Updated RateLimitInfo
 * @throws Error if rate limit exceeded
 */
export function incrementRateLimit(userId: string, userRole?: string): RateLimitInfo {
  const info = checkRateLimit(userId, userRole);

  if (info.requestCount >= info.limit) {
    const resetIn = Math.ceil((info.windowEnd - Date.now()) / 1000);
    logger.warn(`Rate limit exceeded for user ${userId}. Reset in ${resetIn}s`);

    throw {
      status: 429,
      message: `Rate limit exceeded. You can make ${info.limit} requests per minute. Please try again in ${resetIn} seconds.`,
      retryAfter: resetIn,
    };
  }

  info.requestCount++;
  rateLimitStore.set(userId, info);

  return info;
}

/**
 * Get remaining requests for a user
 */
export function getRemainingRequests(userId: string, userRole?: string): number {
  const info = checkRateLimit(userId, userRole);
  return Math.max(0, info.limit - info.requestCount);
}

/**
 * Reset rate limit for a user (admin function)
 */
export function resetRateLimit(userId: string): void {
  rateLimitStore.delete(userId);
  logger.info(`Rate limit reset for user ${userId}`);
}

/**
 * Get all rate limit stats (admin function)
 */
export function getRateLimitStats(): Map<string, RateLimitInfo> {
  return new Map(rateLimitStore);
}
"}

{"file_path": "src/lib/utils/content-validator.ts", "initial_content": "/**
 * Content validation and sanitization utilities
 */

import { ContextLimits } from '@/types';
import { logger } from './logger';

/**
 * Default context size limits
 */
export const DEFAULT_CONTEXT_LIMITS: ContextLimits = {
  maxContextSize: 5 * 1024 * 1024, // 5MB total context
  maxExternalFiles: 10,
  maxSectionReferences: 20,
};

/**
 * Calculate byte size of a string
 */
function getByteSize(str: string): number {
  return new Blob([str]).size;
}

/**
 * Validate context size doesn't exceed limits
 */
export function validateContextSize(
  context: Record<string, string>,
  externalContext: Array<{ title: string; content: string }>,
  limits: ContextLimits = DEFAULT_CONTEXT_LIMITS
): { valid: boolean; error?: string; totalSize: number } {
  // Calculate total context size
  const contextSize = Object.values(context).reduce(
    (sum, content) => sum + getByteSize(content),
    0
  );

  const externalSize = externalContext.reduce(
    (sum, item) => sum + getByteSize(item.content),
    0
  );

  const totalSize = contextSize + externalSize;

  // Check total size
  if (totalSize > limits.maxContextSize) {
    return {
      valid: false,
      error: `Context size (${(totalSize / 1024 / 1024).toFixed(2)}MB) exceeds maximum (${(limits.maxContextSize / 1024 / 1024).toFixed(2)}MB)`,
      totalSize,
    };
  }

  // Check number of section references
  if (Object.keys(context).length > limits.maxSectionReferences) {
    return {
      valid: false,
      error: `Too many section references (${Object.keys(context).length}). Maximum is ${limits.maxSectionReferences}`,
      totalSize,
    };
  }

  // Check number of external files
  if (externalContext.length > limits.maxExternalFiles) {
    return {
      valid: false,
      error: `Too many external files (${externalContext.length}). Maximum is ${limits.maxExternalFiles}`,
      totalSize,
    };
  }

  return { valid: true, totalSize };
}

/**
 * Sanitize text content for AI processing
 * Removes potentially problematic characters while preserving formatting
 */
export function sanitizeContent(content: string): string {
  if (!content) return '';

  let sanitized = content;

  // Remove null bytes
  sanitized = sanitized.replace(/\0/g, '');

  // Normalize line endings
  sanitized = sanitized.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // Remove excessive whitespace (but preserve paragraph breaks)
  sanitized = sanitized.replace(/\n{4,}/g, '\n\n\n');

  // Remove control characters except newlines and tabs
  sanitized = sanitized.replace(/[\x00-\x08\x0B-\x0C\x0E-\x1F\x7F]/g, '');

  // Trim leading/trailing whitespace
  sanitized = sanitized.trim();

  return sanitized;
}

/**
 * Sanitize context record
 */
export function sanitizeContext(context: Record<string, string>): Record<string, string> {
  const sanitized: Record<string, string> = {};

  for (const [key, value] of Object.entries(context)) {
    sanitized[key] = sanitizeContent(value);
  }

  return sanitized;
}

/**
 * Sanitize external context array
 */
export function sanitizeExternalContext(
  externalContext: Array<{ title: string; content: string }>
): Array<{ title: string; content: string }> {
  return externalContext.map(item => ({
    title: sanitizeContent(item.title),
    content: sanitizeContent(item.content),
  }));
}

/**
 * Validate and sanitize all input for section generation
 */
export function validateAndSanitizeInput(input: {
  context: Record<string, string>;
  externalContext: Array<{ title: string; content: string }>;
  sectionToGenerate: string;
  prompt: string;
}): {
  valid: boolean;
  error?: string;
  sanitized?: typeof input;
  contextSize?: number;
} {
  // Validate context size
  const sizeValidation = validateContextSize(input.context, input.externalContext);

  if (!sizeValidation.valid) {
    logger.warn(`Context validation failed: ${sizeValidation.error}`);
    return {
      valid: false,
      error: sizeValidation.error,
      contextSize: sizeValidation.totalSize,
    };
  }

  // Sanitize all content
  const sanitized = {
    context: sanitizeContext(input.context),
    externalContext: sanitizeExternalContext(input.externalContext),
    sectionToGenerate: sanitizeContent(input.sectionToGenerate),
    prompt: sanitizeContent(input.prompt),
  };

  logger.info(`Input validated and sanitized. Context size: ${(sizeValidation.totalSize / 1024).toFixed(2)}KB`);

  return {
    valid: true,
    sanitized,
    contextSize: sizeValidation.totalSize,
  };
}
"}

