  const output: GenerateSectionOutput = {
    sectionName: input.sectionToGenerate,
    content: content.trim(),
  };

  if (!output.content || output.content.length === 0) {
    logger.error(`AI generated empty response for section: ${input.sectionToGenerate}`);
    throw new Error(`The AI failed to generate a response for the '${input.sectionToGenerate}' section. Please try again.`);
  }

  logger.info(`✓ Successfully generated section: ${input.sectionToGenerate} (${output.content.length} chars)`);

  return output;
}"}

