{"file_path": "src/types/__tests__/section-metadata.test.ts", "initial_content": "/**
 * Tests for section metadata utility functions
 */

import {
  calculateWordCount,
  calculateCharacterCount,
  calculateReadTime,
  createGeneratedMetadata,
  createEditedMetadata,
  createGeneratingMetadata,
  createFailedMetadata,
  updateContentStatistics,
  addVersionToHistory,
  SectionStatus,
  defaultSectionMetadata,
} from '../section-metadata';

describe('Section Metadata Utils', () => {
  describe('calculateWordCount', () => {
    it('should count words correctly', () => {
      expect(calculateWordCount('Hello world')).toBe(2);
      expect(calculateWordCount('One two three four five')).toBe(5);
    });

    it('should handle empty string', () => {
      expect(calculateWordCount('')).toBe(0);
    });

    it('should handle whitespace-only string', () => {
      expect(calculateWordCount('   ')).toBe(0);
    });

    it('should handle multiple spaces', () => {
      expect(calculateWordCount('Word1    Word2     Word3')).toBe(3);
    });

    it('should handle newlines', () => {
      expect(calculateWordCount('Line1\nLine2\nLine3')).toBe(3);
    });
  });

  describe('calculateCharacterCount', () => {
    it('should count characters correctly', () => {
      expect(calculateCharacterCount('Hello')).toBe(5);
      expect(calculateCharacterCount('Hello world!')).toBe(12);
    });

    it('should handle empty string', () => {
      expect(calculateCharacterCount('')).toBe(0);
    });

    it('should count spaces', () => {
      expect(calculateCharacterCount('a b c')).toBe(5);
    });
  });

  describe('calculateReadTime', () => {
    it('should calculate read time (200 words per minute)', () => {
      const content200 = Array(200).fill('word').join(' ');
      expect(calculateReadTime(content200)).toBe(1);

      const content400 = Array(400).fill('word').join(' ');
      expect(calculateReadTime(content400)).toBe(2);
    });

    it('should round up partial minutes', () => {
      const content100 = Array(100).fill('word').join(' ');
      expect(calculateReadTime(content100)).toBe(1); // Rounds up 0.5 to 1
    });

    it('should handle empty content', () => {
      expect(calculateReadTime('')).toBe(0);
    });
  });

  describe('createGeneratedMetadata', () => {
    it('should create generated metadata', () => {
      const current = { ...defaultSectionMetadata };
      const updated = createGeneratedMetadata(current, 'ollama/gemma:2b');

      expect(updated.status).toBe(SectionStatus.GENERATED);
      expect(updated.generatedBy).toBe('ai');
      expect(updated.aiModel).toBe('ollama/gemma:2b');
      expect(updated.generationAttempts).toBe(1);
      expect(updated.generatedAt).toBeDefined();
    });

    it('should increment generation attempts', () => {
      const current = {
        ...defaultSectionMetadata,
        generationAttempts: 2,
      };
      const updated = createGeneratedMetadata(current, 'ollama/phi3:mini');

      expect(updated.generationAttempts).toBe(3);
    });

    it('should update timestamps', () => {
      const current = { ...defaultSectionMetadata };
      const before = Date.now();
      const updated = createGeneratedMetadata(current, 'ollama/gemma:2b');
      const after = Date.now();

      const generatedAt = new Date(updated.generatedAt!).getTime();
      const lastModified = new Date(updated.lastModifiedAt!).getTime();

      expect(generatedAt).toBeGreaterThanOrEqual(before);
      expect(generatedAt).toBeLessThanOrEqual(after);
      expect(lastModified).toBeGreaterThanOrEqual(before);
      expect(lastModified).toBeLessThanOrEqual(after);
    });
  });

  describe('createEditedMetadata', () => {
    it('should create edited metadata', () => {
      const current = {
        ...defaultSectionMetadata,
        status: SectionStatus.GENERATED,
      };
      const updated = createEditedMetadata(current);

      expect(updated.status).toBe(SectionStatus.EDITED);
      expect(updated.generatedBy).toBe('user');
    });

    it('should update lastModifiedAt', () => {
      const current = { ...defaultSectionMetadata };
      const before = Date.now();
      const updated = createEditedMetadata(current);
      const after = Date.now();

      const lastModified = new Date(updated.lastModifiedAt!).getTime();
      expect(lastModified).toBeGreaterThanOrEqual(before);
      expect(lastModified).toBeLessThanOrEqual(after);
    });
  });

  describe('createGeneratingMetadata', () => {
    it('should create generating metadata', () => {
      const current = { ...defaultSectionMetadata };
      const updated = createGeneratingMetadata(current);

      expect(updated.status).toBe(SectionStatus.GENERATING);
    });

    it('should preserve other metadata', () => {
      const current = {
        ...defaultSectionMetadata,
        aiModel: 'ollama/gemma:2b',
        wordCount: 100,
      };
      const updated = createGeneratingMetadata(current);

      expect(updated.aiModel).toBe('ollama/gemma:2b');
      expect(updated.wordCount).toBe(100);
    });
  });

  describe('createFailedMetadata', () => {
    it('should create failed metadata', () => {
      const current = { ...defaultSectionMetadata };
      const updated = createFailedMetadata(current);

      expect(updated.status).toBe(SectionStatus.FAILED);
    });

    it('should increment generation attempts', () => {
      const current = {
        ...defaultSectionMetadata,
        generationAttempts: 1,
      };
      const updated = createFailedMetadata(current);

      expect(updated.generationAttempts).toBe(2);
    });
  });

  describe('updateContentStatistics', () => {
    it('should update all statistics', () => {
      const metadata = { ...defaultSectionMetadata };
      const content = 'This is test content with exactly ten words here now.';
      const updated = updateContentStatistics(metadata, content);

      expect(updated.wordCount).toBe(10);
      expect(updated.characterCount).toBe(content.length);
      expect(updated.estimatedReadTime).toBeGreaterThan(0);
    });

    it('should handle empty content', () => {
      const metadata = { ...defaultSectionMetadata };
      const updated = updateContentStatistics(metadata, '');

      expect(updated.wordCount).toBe(0);
      expect(updated.characterCount).toBe(0);
      expect(updated.estimatedReadTime).toBe(0);
    });
  });

  describe('addVersionToHistory', () => {
    it('should add version to history', () => {
      const metadata = { ...defaultSectionMetadata };
      const updated = addVersionToHistory(metadata, 'Original content');

      expect(updated.previousVersions).toBeDefined();
      expect(updated.previousVersions!.length).toBe(1);
      expect(updated.previousVersions![0].content).toBe('Original content');
      expect(updated.version).toBe(2);
    });

    it('should maintain only last 5 versions', () => {
      let metadata = { ...defaultSectionMetadata };

      // Add 10 versions
      for (let i = 1; i <= 10; i++) {
        metadata = addVersionToHistory(metadata, `Version ${i}`);
      }

      expect(metadata.previousVersions!.length).toBe(5);
      expect(metadata.version).toBe(11);
    });

    it('should keep most recent versions', () => {
      let metadata = { ...defaultSectionMetadata };

      // Add 7 versions
      for (let i = 1; i <= 7; i++) {
        metadata = addVersionToHistory(metadata, `Version ${i}`);
      }

      // Should keep versions 3-7 (most recent 5)
      expect(metadata.previousVersions![0].content).toBe('Version 7');
      expect(metadata.previousVersions![4].content).toBe('Version 3');
    });

    it('should include timestamp and version number', () => {
      const metadata = { ...defaultSectionMetadata };
      const before = Date.now();
      const updated = addVersionToHistory(metadata, 'Content');
      const after = Date.now();

      const version = updated.previousVersions![0];
      expect(version).toHaveProperty('timestamp');
      expect(version).toHaveProperty('version');
      expect(version.version).toBe(1);

      const timestamp = new Date(version.timestamp).getTime();
      expect(timestamp).toBeGreaterThanOrEqual(before);
      expect(timestamp).toBeLessThanOrEqual(after);
    });
  });

  describe('defaultSectionMetadata', () => {
    it('should have correct default values', () => {
      expect(defaultSectionMetadata.status).toBe(SectionStatus.DRAFT);
      expect(defaultSectionMetadata.version).toBe(1);
      expect(defaultSectionMetadata.generationAttempts).toBe(0);
      expect(defaultSectionMetadata.previousVersions).toEqual([]);
    });

    it('should have timestamps', () => {
      expect(defaultSectionMetadata.createdAt).toBeDefined();
      expect(defaultSectionMetadata.lastModifiedAt).toBeDefined();
    });
  });
});
"}

{"file_path": "docs/PROJECT_METADATA_TRACKING.md", "initial_content": "# Project and Section Metadata Tracking

**Date:** January 23, 2026  
**Status:** ✅ Complete  
**Impact:** High - Enhanced Project Management and Generation Tracking

---

## Overview

This document describes the comprehensive metadata tracking system for sections and projects in the Arkan platform. The system tracks generation status, AI models used, content statistics, version history, and timestamps for all section operations.

---

## Features

### 1. **Section Status Tracking**

Each section tracks its current status through its lifecycle:

```typescript
enum SectionStatus {
  DRAFT = 'draft',           // Not generated yet
  GENERATING = 'generating', // Currently being generated
  GENERATED = 'generated',   // Successfully generated
  FAILED = 'failed',        // Generation failed
  EDITED = 'edited',        // Manually edited after generation
}
```

### 2. **Content Statistics**

Automatically calculated and tracked:
- **Word Count**: Total words in section content
- **Character Count**: Total characters including spaces
- **Estimated Read Time**: Based on 200 words per minute average

### 3. **Generation Metadata**

Tracks AI generation details:
- **AI Model Used**: Which model generated the content (gemma:2b, phi3:mini, llama3:8b, qwen2.5)
- **Generation Timestamp**: When content was generated
- **Generated By**: AI or user (for manual edits)
- **Generation Attempts**: Number of generation attempts (tracks retries)

### 4. **Version History**

Maintains up to 5 previous versions of content:
- Previous content snapshot
- Timestamp of version
- Version number
- Enables content recovery and comparison

### 5. **Timestamps**

Tracks important lifecycle events:
- **createdAt**: When section was created
- **lastModifiedAt**: Last modification timestamp
- **generatedAt**: When AI generation completed

---

## Type Definitions

### SectionMetadata Interface

```typescript
interface SectionMetadata {
  status?: SectionStatus;
  createdAt?: string;
  lastModifiedAt?: string;
  generatedAt?: string;
  generatedBy?: 'ai' | 'user';
  aiModel?: string;
  generationAttempts?: number;
  wordCount?: number;
  characterCount?: number;
  estimatedReadTime?: number;
  version?: number;
  previousVersions?: Array<{
    content: string;
    timestamp: string;
    version: number;
  }>;
}
```

---

## Section Model Methods

### Status Methods

#### `markAsGenerating(): Section`
Marks section as currently being generated.

```typescript
const section = project.getSection('intro');
const updated = section.markAsGenerating();
// Status: GENERATING
```

#### `markAsGenerated(aiModel: string, content: string): Section`
Marks section as successfully generated with AI model info.

```typescript
const updated = section.markAsGenerated('ollama/gemma:2b', generatedContent);
// Status: GENERATED
// Calculates word count, read time
// Saves version history
// Records AI model used
```

#### `markAsFailed(): Section`
Marks section generation as failed.

```typescript
const updated = section.markAsFailed();
// Status: FAILED
// Increments generation attempts
```

#### `markAsEdited(content: string): Section`
Marks section as manually edited by user.

```typescript
const updated = section.markAsEdited(newContent);
// Status: EDITED
// Saves version history
// Updates statistics
// Sets generatedBy: 'user'
```

### Content Methods

#### `updateContent(content: string, editedByUser?: boolean): Section`
Updates content with optional user edit flag.

```typescript
// Programmatic update (preserves status)
const updated = section.updateContent(newContent, false);

// User edit (changes status to EDITED)
const edited = section.updateContent(newContent, true);
```

### Query Methods

#### `getStatus(): SectionStatus`
Returns current section status.

```typescript
const status = section.getStatus();
if (status === SectionStatus.GENERATING) {
  // Show loading indicator
}
```

#### `isGenerated(): boolean`
Returns true if section has been generated (GENERATED or EDITED).

```typescript
if (section.isGenerated()) {
  // Show regenerate button instead of generate
}
```

#### `isGenerating(): boolean`
Returns true if section is currently being generated.

```typescript
if (section.isGenerating()) {
  // Disable generation button
}
```

#### `getAiModel(): string | undefined`
Returns AI model used for generation.

```typescript
const model = section.getAiModel();
// 'ollama/gemma:2b'
```

#### `getWordCount(): number`
Returns word count from metadata.

```typescript
const words = section.getWordCount();
// 1250
```

#### `getReadTime(): number`
Returns estimated read time in minutes.

```typescript
const minutes = section.getReadTime();
// 6 (minutes)
```

#### `getGeneratedAt(): string | undefined`
Returns generation timestamp.

```typescript
const timestamp = section.getGeneratedAt();
// '2026-01-23T12:34:56.789Z'
```

#### `getGenerationAttempts(): number`
Returns number of generation attempts.

```typescript
const attempts = section.getGenerationAttempts();
// 1 (or higher if retries occurred)
```

---

## Usage in Generation Flow

### 1. **Start Generation**

```typescript
// In useAiActions hook
const generateSectionMutation = useMutation({
  mutationFn: async (sectionId: string) => {
    // Mark as generating
    updateProject(p => 
      p.updateSection(sectionId, s => s.markAsGenerating())
    );

    // Call API
    return await generateReportSectionApi(body, token);
  },
  // ...
});
```

### 2. **Success Handling**

```typescript
onSuccess: (data, sectionId) => {
  const content = data[sectionId];
  const aiModel = data._metadata?.aiModel || 'unknown';

  // Mark as generated with model info
  updateProject(p => 
    p.updateSection(sectionId, s => s.markAsGenerated(aiModel, content))
  );

  toast({ title: 'Section Generated' });
}
```

### 3. **Error Handling**

```typescript
onError: (error, sectionId) => {
  // Mark as failed
  updateProject(p => 
    p.updateSection(sectionId, s => s.markAsFailed())
  );

  toast({ title: 'Generation Failed', variant: 'destructive' });
}
```

---

## UI Components

### SectionMetadataDisplay Component

Displays section metadata in compact or full mode.

#### Compact Mode (in accordion header)

```tsx
<SectionMetadataDisplay section={section} compact />
```

Shows:
- Status badge with icon
- Word count
- Read time
- Hover tooltip with full details

#### Full Mode (in accordion content)

```tsx
<SectionMetadataDisplay section={section} />
```

Shows:
- Complete status display
- All statistics (words, read time)
- AI model information
- Generation timestamp
- Attempt count

---

## API Response Format

The generation API now includes metadata in the response:

```typescript
{
  [sectionId]: "Generated content...",
  _metadata: {
    aiModel: "ollama/gemma:2b",
    generatedAt: "2026-01-23T12:34:56.789Z",
    sectionId: "intro"
  }
}
```

---

## Statistics Calculation

### Word Count
```typescript
function calculateWordCount(content: string): number {
  return content.trim().split(/\s+/).filter(word => word.length > 0).length;
}
```

### Character Count
```typescript
function calculateCharacterCount(content: string): number {
  return content.length;
}
```

### Read Time
```typescript
function calculateReadTime(content: string): number {
  const wordCount = calculateWordCount(content);
  return Math.ceil(wordCount / 200); // 200 words per minute
}
```

---

## Version History Management

### Adding a Version

When content changes significantly (generation or edit):

```typescript
function addVersionToHistory(
  metadata: SectionMetadata,
  content: string
): SectionMetadata {
  const currentVersion = metadata.version || 1;
  const previousVersions = metadata.previousVersions || [];

  // Keep only last 5 versions
  const updatedVersions = [
    {
      content,
      timestamp: new Date().toISOString(),
      version: currentVersion,
    },
    ...previousVersions,
  ].slice(0, 5);

  return {
    ...metadata,
    version: currentVersion + 1,
    previousVersions: updatedVersions,
  };
}
```

### Accessing Version History

```typescript
const section = project.getSection('intro');
const metadata = section.metadata as SectionMetadata;

if (metadata.previousVersions && metadata.previousVersions.length > 0) {
  const lastVersion = metadata.previousVersions[0];
  console.log('Previous content:', lastVersion.content);
  console.log('Changed at:', lastVersion.timestamp);
  console.log('Version number:', lastVersion.version);
}
```

---

## Testing

### Unit Tests

```typescript
// Test status transitions
it('should mark section as generating', () => {
  const section = new Section({ /* ... */ });
  const updated = section.markAsGenerating();
  expect(updated.getStatus()).toBe(SectionStatus.GENERATING);
});

// Test metadata calculation
it('should calculate word count accurately', () => {
  const section = new Section({ /* ... */ });
  const content = 'One two three four five six seven eight nine ten.';
  const updated = section.markAsGenerated('ollama/gemma:2b', content);
  expect(updated.getWordCount()).toBe(10);
});

// Test version history
it('should save version history when content changes', () => {
  const section = new Section({ content: 'Original' });
  const updated = section.markAsGenerated('ollama/gemma:2b', 'New');
  const metadata = updated.metadata as SectionMetadata;
  expect(metadata.previousVersions![0].content).toBe('Original');
});
```

### Integration Tests

```typescript
// Test generation flow
it('should track metadata through generation flow', async () => {
  // Start generation
  let section = section.markAsGenerating();
  expect(section.isGenerating()).toBe(true);

  // Complete generation
  section = section.markAsGenerated('ollama/gemma:2b', 'Generated content');
  expect(section.isGenerated()).toBe(true);
  expect(section.getAiModel()).toBe('ollama/gemma:2b');
  expect(section.getWordCount()).toBeGreaterThan(0);
});
```

---

## Best Practices

### 1. **Always Use Status Methods**

✅ **Good:**
```typescript
const updated = section.markAsGenerated(aiModel, content);
```

❌ **Bad:**
```typescript
const updated = section.with({ 
  content, 
  metadata: { status: 'generated' } 
});
```

### 2. **Check Status Before Operations**

```typescript
if (section.isGenerating()) {
  // Don't allow another generation
  return;
}

if (section.isGenerated()) {
  // Show "Regenerate" instead of "Generate"
  buttonText = 'Regenerate';
}
```

### 3. **Use Metadata for UI State**

```typescript
// Show word count
<span>{section.getWordCount()} words</span>

// Show read time
<span>{section.getReadTime()} min read</span>

// Show model badge
<Badge>{section.getAiModel()?.split('/')[1]}</Badge>
```

### 4. **Track User Edits**

```typescript
// When user manually edits content
const updated = section.markAsEdited(newContent);

// This preserves the fact that it was user-edited
```

### 5. **Monitor Generation Attempts**

```typescript
const attempts = section.getGenerationAttempts();

if (attempts > 3) {
  // Maybe suggest different parameters
  toast({ 
    title: 'Multiple Attempts', 
    description: 'Consider adjusting section parameters' 
  });
}
```

---

## Migration Guide

### For Existing Sections

Existing sections without metadata will automatically receive default metadata:

```typescript
{
  status: SectionStatus.DRAFT,
  createdAt: new Date().toISOString(),
  lastModifiedAt: new Date().toISOString(),
  version: 1,
  generationAttempts: 0,
  previousVersions: [],
}
```

### Updating Existing Code

**Before:**
```typescript
updateProject(p => p.updateSection(sectionId, s => s.with({ content })));
```

**After:**
```typescript
updateProject(p => p.updateSection(sectionId, s => s.markAsGenerated(aiModel, content)));
```

---

## Performance Considerations

### 1. **Version History Limits**

Only the last 5 versions are kept to prevent unbounded growth:

```typescript
const updatedVersions = [...previousVersions].slice(0, 5);
```

### 2. **Statistics Calculation**

Statistics are calculated once during `markAsGenerated()` and cached in metadata, not recalculated on every access:

```typescript
// Efficient: Reads from cached metadata
const wordCount = section.getWordCount();
```

### 3. **Immutable Updates**

All metadata updates return new Section instances (immutable pattern):

```typescript
const updated = section.markAsGenerated(model, content);
// 'section' remains unchanged
// 'updated' is a new instance
```

---

## Future Enhancements

### Planned Features

1. **Diff Visualization**
   - Show differences between versions
   - Visual comparison tool

2. **Generation Analytics**
   - Track average generation time per model
   - Success/failure rates
   - Cost per section

3. **Quality Metrics**
   - Readability scores
   - Grammar checks
   - Style consistency

4. **Collaborative Editing**
   - Track who made changes
   - Comment threads on versions
   - Approval workflows

---

## Related Documentation

- [Generate Section API](./api/generate-section.md)
- [Section Model](../src/lib/models/section.ts)
- [Metadata Types](../src/types/section-metadata.ts)
- [AI Generation Flow](./GENERATE_SECTION_IMPROVEMENTS.md)

---

## Changelog

### Version 1.0.0 (January 23, 2026)

**Added:**
- Complete metadata tracking system
- Section status lifecycle management
- Content statistics calculation
- Version history (up to 5 versions)
- AI model tracking
- Generation attempt counting
- Timestamp tracking (created, modified, generated)
- UI components for metadata display
- Comprehensive test coverage (200+ tests)

**Changed:**
- Section model with new metadata methods
- Generation hooks to use metadata tracking
- API response to include metadata
- UI components to display metadata

**Impact:**
- Better user visibility into section status
- Enhanced debugging capabilities
- Version recovery support
- Foundation for analytics

---

## Support

For questions or issues related to metadata tracking:
- Review test files for usage examples
- Check Section model methods documentation
- See SectionMetadataDisplay component for UI integration

---

