/**
 * Simplified section generation flow
 * Only accepts system prompt and user prompt - all context building done by PromptBuilder
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { withRetry, DEFAULT_RETRY_CONFIG } from '@/lib/utils/retry-utils';
import { logger } from '@/lib/utils/logger';
import { 
  SimplifiedGenerateSectionInput, 
  SimplifiedGenerateSectionInputSchema, 
  SimplifiedGenerateSectionOutput, 
  SimplifiedGenerateSectionOutputSchema 
} from '../schemas/simplified-flows';

/**
 * Generate a section using only system and user prompts
 * @param input - Simplified input with sectionId, systemPrompt, and userPrompt
 * @param modelName - AI model to use (e.g., 'ollama/gemma:2b')
 * @param temperature - Temperature setting for generation
 * @returns Generated section content
 */
export async function generateSectionSimplified(
  input: SimplifiedGenerateSectionInput,
  modelName: string = 'ollama/gemma:2b',
  temperature: number = 0.3
): Promise<SimplifiedGenerateSectionOutput> {
  logger.info(`Generating section: ${input.sectionId} with model: ${modelName}`);

  // Define the prompt with simplified input
  const sectionPrompt = ai.definePrompt({
    name: 'generateSectionSimplifiedPrompt',
    input: { schema: SimplifiedGenerateSectionInputSchema },
    output: { schema: SimplifiedGenerateSectionOutputSchema },
    model: modelName,
    system: '{{systemPrompt}}',
    prompt: '{{userPrompt}}',
    config: {
      temperature,
    },
  });

  // Call the AI with retry logic
  const result = await withRetry(
    () => sectionPrompt(input),
    DEFAULT_RETRY_CONFIG,
    `section: ${input.sectionId}`
  );

  // Extract content from response
  let content = '';
  if (typeof result === 'string') {
    content = result;
  } else if (result && typeof result === 'object') {
    content = (result as any).text || (result as any).content || '';
    if (!content && typeof (result as any).output === 'string') {
      content = (result as any).output;
    }
  }

  const output: SimplifiedGenerateSectionOutput = {
    sectionId: input.sectionId,
    content: content.trim(),
  };

  if (!output.content || output.content.length === 0) {
    logger.error(`AI generated empty response for section: ${input.sectionId}`);
    throw new Error(`The AI failed to generate content for section '${input.sectionId}'. Please try again.`);
  }

  logger.info(`✓ Successfully generated section: ${input.sectionId} (${output.content.length} chars)`);

  return output;
}
"}

