{"file_path": "src/ai/schemas/unified-generation.ts", "initial_content": "/**
 * Unified AI Generation Schema
 * Single interface for all text generation tasks (Section, Grammar, Translation, etc.)
 */

import { z } from 'zod';

/**
 * Process types for different generation tasks
 */
export enum GenerationProcessType {
  SECTION = 'section',           // Generate report sections
  GRAMMAR = 'grammar',           // Grammar correction
  TRANSLATION = 'translation',   // Text translation
  SUMMARIZATION = 'summarization', // Text summarization
  EXPANSION = 'expansion',       // Text expansion
  REWRITE = 'rewrite',          // Text rewriting
  CHAT = 'chat',                // Chat/conversation
  CUSTOM = 'custom',            // Custom generation
}

/**
 * Unified input schema for all generation requests
 */
export const UnifiedGenerationInputSchema = z.object({
  // Process identification
  processType: z.nativeEnum(GenerationProcessType)
    .describe('Type of generation process'),

  processId: z.string().min(1)
    .describe('Unique identifier for this generation (e.g., section-id, task-id)'),

  // Prompts (required)
  systemPrompt: z.string().min(10)
    .describe('System instructions defining AI role and behavior'),

  userPrompt: z.string().min(10)
    .describe('User task description and context'),

  // Optional configuration
  modelConfig: z.object({
    modelName: z.string().optional()
      .describe('AI model to use (e.g., ollama/gemma:2b)'),
    temperature: z.number().min(0).max(2).optional()
      .describe('Temperature for generation (0.0-2.0)'),
    maxTokens: z.number().positive().optional()
      .describe('Maximum tokens to generate'),
  }).optional(),

  // Optional metadata for logging/tracking
  metadata: z.record(z.any()).optional()
    .describe('Additional metadata for logging'),
});

export type UnifiedGenerationInput = z.infer<typeof UnifiedGenerationInputSchema>;

/**
 * Unified output schema for all generation responses
 */
export const UnifiedGenerationOutputSchema = z.object({
  processType: z.nativeEnum(GenerationProcessType)
    .describe('Type of generation process'),

  processId: z.string()
    .describe('Unique identifier for this generation'),

  content: z.string()
    .describe('Generated content (plain markdown text)'),

  metadata: z.object({
    modelUsed: z.string()
      .describe('AI model that generated the content'),
    generatedAt: z.string()
      .describe('ISO timestamp of generation'),
    tokensUsed: z.number().optional()
      .describe('Number of tokens used (if available)'),
    processingTimeMs: z.number().optional()
      .describe('Processing time in milliseconds'),
  }),
});

export type UnifiedGenerationOutput = z.infer<typeof UnifiedGenerationOutputSchema>;

/**
 * Default model configurations for different process types
 */
export const DEFAULT_MODEL_CONFIGS: Record<GenerationProcessType, {
  modelName: string;
  temperature: number;
  maxTokens?: number;
}> = {
  [GenerationProcessType.SECTION]: {
    modelName: 'ollama/gemma:2b',
    temperature: 0.3,
    maxTokens: 3000,
  },
  [GenerationProcessType.GRAMMAR]: {
    modelName: 'ollama/phi3:mini',
    temperature: 0.1, // Low for accuracy
    maxTokens: 2000,
  },
  [GenerationProcessType.TRANSLATION]: {
    modelName: 'ollama/phi3:mini',
    temperature: 0.2,
    maxTokens: 2000,
  },
  [GenerationProcessType.SUMMARIZATION]: {
    modelName: 'ollama/gemma:2b',
    temperature: 0.3,
    maxTokens: 1000,
  },
  [GenerationProcessType.EXPANSION]: {
    modelName: 'ollama/llama3:8b',
    temperature: 0.5,
    maxTokens: 3000,
  },
  [GenerationProcessType.REWRITE]: {
    modelName: 'ollama/phi3:mini',
    temperature: 0.4,
    maxTokens: 2000,
  },
  [GenerationProcessType.CHAT]: {
    modelName: 'ollama/llama3:8b',
    temperature: 0.7,
    maxTokens: 2000,
  },
  [GenerationProcessType.CUSTOM]: {
    modelName: 'ollama/gemma:2b',
    temperature: 0.5,
    maxTokens: 2000,
  },
};

/**
 * Helper to get default model config for a process type
 */
export function getDefaultModelConfig(processType: GenerationProcessType) {
  return DEFAULT_MODEL_CONFIGS[processType];
}

/**
 * Helper to merge user config with defaults
 */
export function mergeModelConfig(
  processType: GenerationProcessType,
  userConfig?: UnifiedGenerationInput['modelConfig']
) {
  const defaults = getDefaultModelConfig(processType);

  return {
    modelName: userConfig?.modelName || defaults.modelName,
    temperature: userConfig?.temperature ?? defaults.temperature,
    maxTokens: userConfig?.maxTokens || defaults.maxTokens,
  };
}
"}

{"file_path": "src/ai/flows/generate-unified.ts", "initial_content": "'use server';

/**
 * Unified AI Generation Flow
 * Single flow that handles all text generation tasks
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { withRetry, DEFAULT_RETRY_CONFIG } from '@/lib/utils/retry-utils';
import { logger } from '@/lib/utils/logger';
import {
  UnifiedGenerationInput,
  UnifiedGenerationInputSchema,
  UnifiedGenerationOutput,
  UnifiedGenerationOutputSchema,
  mergeModelConfig,
} from '../schemas/unified-generation';

/**
 * Universal text generation function
 * Handles all generation types: Section, Grammar, Translation, etc.
 * 
 * @param input - Unified generation input with system/user prompts
 * @returns Generated content with metadata
 */
export async function generateUnified(
  input: UnifiedGenerationInput
): Promise<UnifiedGenerationOutput> {
  const startTime = Date.now();

  logger.info(`Starting ${input.processType} generation for ${input.processId}`);

  // Merge user config with process-specific defaults
  const modelConfig = mergeModelConfig(input.processType, input.modelConfig);

  logger.info(`Using model: ${modelConfig.modelName} (temp: ${modelConfig.temperature})`);

  // Define the prompt with unified input
  // No output schema - let models generate plain text (works best for all model sizes)
  const unifiedPrompt = ai.definePrompt({
    name: 'unifiedGenerationPrompt',
    input: { schema: UnifiedGenerationInputSchema },
    // No output schema - plain text generation
    model: modelConfig.modelName,
    system: '{{systemPrompt}}',
    prompt: '{{userPrompt}}',
    config: {
      temperature: modelConfig.temperature,
      ...(modelConfig.maxTokens && { maxOutputTokens: modelConfig.maxTokens }),
    },
  });

  // Call the AI with retry logic
  const result = await withRetry(
    () => unifiedPrompt(input),
    DEFAULT_RETRY_CONFIG,
    `${input.processType}: ${input.processId}`
  );

  // Extract content from response (handle various formats)
  const content = extractContent(result);

  const endTime = Date.now();
  const processingTimeMs = endTime - startTime;

  // Build output with metadata
  const output: UnifiedGenerationOutput = {
    processType: input.processType,
    processId: input.processId,
    content: content.trim(),
    metadata: {
      modelUsed: modelConfig.modelName,
      generatedAt: new Date().toISOString(),
      processingTimeMs,
    },
  };

  // Validate output has content
  if (!output.content || output.content.length === 0) {
    logger.error(`AI generated empty response for ${input.processType}: ${input.processId}`);
    throw new Error(
      `The AI failed to generate content for ${input.processType} '${input.processId}'. Please try again.`
    );
  }

  logger.info(
    `✓ Successfully generated ${input.processType}: ${input.processId} ` +
    `(${output.content.length} chars in ${processingTimeMs}ms)`
  );

  return output;
}

/**
 * Extract content from various AI response formats
 * Handles string responses, object responses, and candidates arrays
 */
function extractContent(result: unknown): string {
  // Direct string response (most common)
  if (typeof result === 'string') {
    return result;
  }

  // Object response - try various field names
  if (result && typeof result === 'object') {
    const resultObj = result as any;

    // Try common field names
    const content = 
      resultObj.text ||
      resultObj.content ||
      resultObj.output ||
      resultObj.response ||
      resultObj.message ||
      '';

    if (content) {
      return content;
    }

    // Try candidates array (some model implementations)
    if (resultObj.candidates && Array.isArray(resultObj.candidates)) {
      const candidate = resultObj.candidates[0];
      if (candidate) {
        return candidate.content || candidate.text || candidate.output || '';
      }
    }

    // Try data field
    if (resultObj.data) {
      return extractContent(resultObj.data);
    }
  }

  // If we got here, no content found
  return '';
}

/**
 * Batch generation - generate multiple items in parallel
 * Useful for generating multiple sections, corrections, etc.
 */
export async function generateUnifiedBatch(
  inputs: UnifiedGenerationInput[]
): Promise<Array<{ success: boolean; result?: UnifiedGenerationOutput; error?: Error }>> {
  logger.info(`Starting batch generation: ${inputs.length} items`);

  const promises = inputs.map(input =>
    generateUnified(input)
      .then(result => ({ success: true as const, result }))
      .catch(error => ({
        success: false as const,
        error: error instanceof Error ? error : new Error(String(error)),
      }))
  );

  const results = await Promise.all(promises);

  const successCount = results.filter(r => r.success).length;
  logger.info(`Batch generation complete: ${successCount}/${inputs.length} succeeded`);

  return results;
}
"}

{"file_path": "src/app/api/generate/route.ts", "initial_content": "'use server';

/**
 * Unified Generate API Route
 * Single endpoint for all text generation tasks
 * 
 * POST /api/generate
 * 
 * Supports:
 * - Section generation
 * - Grammar correction
 * - Translation
 * - Summarization
 * - Rewriting
 * - Custom generation
 */

import { generateUnified } from '@/ai/flows/generate-unified';
import { UnifiedGenerationInputSchema } from '@/ai/schemas/unified-generation';
import { createApiResponse, handleApiError, withAuth } from '@/lib/utils/api-utils';
import { deductCredit, refundCredit } from '@/services/credit-service';
import { logGeneration } from '@/services/generation-service';
import { incrementRateLimit } from '@/lib/utils/rate-limiter';
import { logger } from '@/lib/utils/logger';

/**
 * POST /api/generate
 * Unified generation endpoint for all text generation tasks
 */
export const POST = withAuth(async ({ request, user }) => {
  const creditCost = 1;
  let creditsDeducted = false;

  try {
    // Parse and validate request body
    const body = await request.json();
    const validation = UnifiedGenerationInputSchema.safeParse(body);

    if (!validation.success) {
      logger.error(`Validation error for user ${user.id}: ${validation.error.message}`);
      return handleApiError(validation.error);
    }

    const input = validation.data;

    // Check rate limit before processing
    try {
      incrementRateLimit(user.id, user.role);
    } catch (rateLimitError) {
      logger.warn(`Rate limit exceeded for user ${user.id}`);
      return handleApiError(rateLimitError);
    }

    // Deduct credits before generation
    await deductCredit(user.id, creditCost);
    creditsDeducted = true;

    logger.info(
      `Starting ${input.processType} generation for user ${user.id}, ` +
      `process: ${input.processId}`
    );

    // Generate with unified AI flow (includes retry logic)
    const result = await generateUnified(input);

    // Log successful generation
    await logGeneration({
      agentId: `${input.processType}-${input.processId}`,
      userId: user.id,
      input: input,
      output: result,
      creditCost: creditCost,
    });

    logger.info(
      `✓ ${input.processType} generation completed for user ${user.id} ` +
      `(${result.content.length} chars in ${result.metadata.processingTimeMs}ms)`
    );

    return createApiResponse(result, 200);

  } catch (error) {
    // Refund credits if generation failed after deduction
    if (creditsDeducted) {
      try {
        await refundCredit(user.id, creditCost);
        logger.info(`Credits refunded to user ${user.id} after generation failure`);
      } catch (refundError) {
        logger.error(`Failed to refund credits to user ${user.id}: ${refundError}`);
        // Continue to throw original error
      }
    }

    logger.error(`Generation failed for user ${user.id}: ${error}`);
    return handleApiError(error);
  }
});
"}

{"file_path": "src/services/api/unifiedGenerationService.ts", "initial_content": "'use client';

/**
 * Unified Generation Service
 * Client-side service for calling the unified generation API
 */

import {
  UnifiedGenerationInput,
  UnifiedGenerationOutput,
  GenerationProcessType,
} from '@/ai/schemas/unified-generation';

/**
 * Call the unified generation API
 * @param input - Generation input with system/user prompts
 * @param token - Firebase authentication token
 * @returns Generated content with metadata
 */
export async function generateUnifiedApi(
  input: UnifiedGenerationInput,
  token: string
): Promise<UnifiedGenerationOutput> {
  const response = await fetch('/api/generate', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify(input),
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(error.message || 'Failed to generate content');
  }

  return await response.json();
}

/**
 * Generate a report section
 * @param sectionId - Section identifier
 * @param systemPrompt - System instructions for the AI
 * @param userPrompt - User task description
 * @param token - Firebase authentication token
 * @param modelConfig - Optional model configuration
 */
export async function generateSection(
  sectionId: string,
  systemPrompt: string,
  userPrompt: string,
  token: string,
  modelConfig?: UnifiedGenerationInput['modelConfig']
): Promise<UnifiedGenerationOutput> {
  return generateUnifiedApi(
    {
      processType: GenerationProcessType.SECTION,
      processId: sectionId,
      systemPrompt,
      userPrompt,
      modelConfig,
    },
    token
  );
}

/**
 * Correct grammar in text
 * @param textId - Text identifier
 * @param text - Text to correct
 * @param token - Firebase authentication token
 */
export async function correctGrammar(
  textId: string,
  text: string,
  token: string
): Promise<UnifiedGenerationOutput> {
  const systemPrompt = `You are an expert grammar and spelling checker. 
Your task is to correct grammar, spelling, punctuation, and style issues while preserving the original meaning and tone.

Instructions:
- Fix all grammar and spelling errors
- Improve punctuation and sentence structure
- Maintain the original voice and style
- Do NOT change the meaning
- Return ONLY the corrected text (no explanations)`;

  const userPrompt = `Please correct the grammar and spelling in the following text:

${text}

Return only the corrected version.`;

  return generateUnifiedApi(
    {
      processType: GenerationProcessType.GRAMMAR,
      processId: textId,
      systemPrompt,
      userPrompt,
      modelConfig: {
        temperature: 0.1, // Low temperature for accuracy
      },
    },
    token
  );
}

/**
 * Translate text
 * @param textId - Text identifier
 * @param text - Text to translate
 * @param targetLanguage - Target language (e.g., 'Spanish', 'French')
 * @param token - Firebase authentication token
 */
export async function translateText(
  textId: string,
  text: string,
  targetLanguage: string,
  token: string
): Promise<UnifiedGenerationOutput> {
  const systemPrompt = `You are an expert translator.
Your task is to translate text accurately while preserving meaning, tone, and style.

Instructions:
- Translate naturally and fluently
- Preserve the original tone and formality
- Keep technical terms accurate
- Maintain formatting (markdown, lists, etc.)
- Return ONLY the translated text`;

  const userPrompt = `Translate the following text to ${targetLanguage}:

${text}

Return only the translated version.`;

  return generateUnifiedApi(
    {
      processType: GenerationProcessType.TRANSLATION,
      processId: textId,
      systemPrompt,
      userPrompt,
    },
    token
  );
}

/**
 * Summarize text
 * @param textId - Text identifier
 * @param text - Text to summarize
 * @param maxWords - Maximum words in summary (optional)
 * @param token - Firebase authentication token
 */
export async function summarizeText(
  textId: string,
  text: string,
  token: string,
  maxWords?: number
): Promise<UnifiedGenerationOutput> {
  const systemPrompt = `You are an expert at creating concise, accurate summaries.
Your task is to extract the key points and main ideas from text.

Instructions:
- Capture the main ideas and key points
- Be concise but comprehensive
- Maintain accuracy - don't add information
- Use clear, simple language
- Return ONLY the summary`;

  const wordLimit = maxWords ? `\n- Keep the summary under ${maxWords} words` : '';

  const userPrompt = `Summarize the following text:${wordLimit}

${text}

Return only the summary.`;

  return generateUnifiedApi(
    {
      processType: GenerationProcessType.SUMMARIZATION,
      processId: textId,
      systemPrompt,
      userPrompt,
    },
    token
  );
}

/**
 * Expand text (make it more detailed)
 * @param textId - Text identifier
 * @param text - Text to expand
 * @param targetLength - Target length description (e.g., '2x longer', '500 words')
 * @param token - Firebase authentication token
 */
export async function expandText(
  textId: string,
  text: string,
  targetLength: string,
  token: string
): Promise<UnifiedGenerationOutput> {
  const systemPrompt = `You are an expert writer skilled at expanding and elaborating on ideas.
Your task is to expand text while maintaining its core message and tone.

Instructions:
- Add relevant details and explanations
- Include examples where appropriate
- Maintain the original tone and style
- Keep it coherent and well-structured
- Return ONLY the expanded text`;

  const userPrompt = `Expand the following text to make it ${targetLength}:

${text}

Return only the expanded version.`;

  return generateUnifiedApi(
    {
      processType: GenerationProcessType.EXPANSION,
      processId: textId,
      systemPrompt,
      userPrompt,
      modelConfig: {
        modelName: 'ollama/llama3:8b', // Use larger model for expansion
      },
    },
    token
  );
}

/**
 * Rewrite text in a different style
 * @param textId - Text identifier
 * @param text - Text to rewrite
 * @param style - Target style (e.g., 'formal', 'casual', 'professional')
 * @param token - Firebase authentication token
 */
export async function rewriteText(
  textId: string,
  text: string,
  style: string,
  token: string
): Promise<UnifiedGenerationOutput> {
  const systemPrompt = `You are an expert writer who can adapt text to different styles.
Your task is to rewrite text in a specific style while preserving the core message.

Instructions:
- Rewrite in the requested style
- Keep the same information and meaning
- Adjust tone, vocabulary, and sentence structure
- Maintain logical flow
- Return ONLY the rewritten text`;

  const userPrompt = `Rewrite the following text in a ${style} style:

${text}

Return only the rewritten version.`;

  return generateUnifiedApi(
    {
      processType: GenerationProcessType.REWRITE,
      processId: textId,
      systemPrompt,
      userPrompt,
    },
    token
  );
}

/**
 * Custom generation with user-provided prompts
 * @param processId - Process identifier
 * @param systemPrompt - System instructions
 * @param userPrompt - User task
 * @param token - Firebase authentication token
 * @param modelConfig - Optional model configuration
 */
export async function generateCustom(
  processId: string,
  systemPrompt: string,
  userPrompt: string,
  token: string,
  modelConfig?: UnifiedGenerationInput['modelConfig']
): Promise<UnifiedGenerationOutput> {
  return generateUnifiedApi(
    {
      processType: GenerationProcessType.CUSTOM,
      processId,
      systemPrompt,
      userPrompt,
      modelConfig,
    },
    token
  );
}
"}

